def main(paragraph: str, data: str, prompt: str) -> dict:
    import json
    import re
    from decimal import Decimal

    for name, value, limit in (
        ("paragraph（原段落）", paragraph, 6000),
        ("prompt（修改提示词）", prompt, 2000),
    ):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("INPUT_EMPTY: " + name + "必须是非空字符串")
        if len(value) > limit:
            raise ValueError("INPUT_LENGTH: " + name + "超过" + str(limit) + "字符")

    # string是正式平台契约；dict仅兼容代码节点单独调试。
    if isinstance(data, dict):
        try:
            data = json.dumps(data, ensure_ascii=False, allow_nan=False)
        except (TypeError, ValueError, RecursionError) as exc:
            raise ValueError("DATA_JSON: 原始数据不是可序列化JSON对象") from exc
    if not isinstance(data, str) or not data.strip():
        raise ValueError("DATA_EMPTY: data必须是JSON对象字符串；仅润色时传{}")
    if len(data) > 24000:
        raise ValueError("DATA_LENGTH: data超过24000字符，请仅提交本段相关数据")

    def unique_object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("DATA_DUPLICATE: 原始数据存在重复键名：" + key)
            result[key] = value
        return result

    def reject_constant(value):
        raise ValueError("DATA_NUMBER: 不允许非标准JSON数值：" + value)

    raw = data.strip().lstrip("\ufeff").strip()
    try:
        parsed = json.loads(
            raw, object_pairs_hook=unique_object,
            parse_float=Decimal, parse_constant=reject_constant,
        )
    except (json.JSONDecodeError, RecursionError) as exc:
        raise ValueError("DATA_JSON: data不是合法JSON，或嵌套过深") from exc
    if not isinstance(parsed, dict):
        raise ValueError("DATA_OBJECT: data顶层必须是对象，明细数组请放在中文字段下")

    def check_keys(value, path, depth):
        if depth > 20:
            raise ValueError("DATA_DEPTH: 原始数据嵌套不能超过20层")
        if isinstance(value, dict):
            for key, child in value.items():
                child_path = path + "." + key
                if not re.search(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]", key) or re.search(r"[A-Za-z]", key):
                    raise ValueError("DATA_KEY: 键名必须含中文且不含英文字母：" + child_path)
                check_keys(child, child_path, depth + 1)
        elif isinstance(value, list):
            for index, child in enumerate(value):
                check_keys(child, path + "[" + str(index) + "]", depth + 1)

    check_keys(parsed, "原始数据", 0)

    # 仅移除字符串外的JSON空白，保留数值原始精度、末尾零和字符串内容。
    compact = []
    in_string = False
    escaped = False
    for char in raw:
        if in_string:
            compact.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            compact.append(char)
            in_string = True
        elif char not in " \t\r\n":
            compact.append(char)

    packet = (
        '{"原段落":' + json.dumps(paragraph, ensure_ascii=False)
        + ',"原始数据":' + "".join(compact)
        + ',"修改提示词":' + json.dumps(prompt, ensure_ascii=False) + "}"
    )
    try:
        packet_bytes = len(packet.encode("utf-8"))
    except UnicodeEncodeError as exc:
        raise ValueError("INPUT_UNICODE: 输入含无效Unicode字符") from exc
    if packet_bytes > 16000:
        raise ValueError("CONTEXT_LIMIT: 段落任务包超过16000字节，请缩短原段落或筛选原始数据；不会截断数据")
    return {"edit_packet": packet}

def main(draft_md: str) -> dict:
    import json
    import re

    if not isinstance(draft_md, str) or not draft_md.strip():
        raise ValueError("OUTPUT_EMPTY: 模型必须返回非空Markdown正文")
    result = draft_md.replace("\r\n", "\n").replace("\r", "\n").strip()
    if len(result) > 4000:
        raise ValueError("OUTPUT_LENGTH: 修改结果超过4000字符，请缩小改写范围后重新运行")
    if re.match(r"\A(?:`{3,}|~{3,})", result):
        raise ValueError("OUTPUT_FENCE: 请直接输出Markdown正文，不要包裹代码围栏")
    try:
        json.loads(result)
    except (ValueError, RecursionError):
        pass
    else:
        raise ValueError("OUTPUT_JSON: 修改结果必须是正文，不能用JSON包装")
    if re.search(r"</?(?:think|thinking|analysis)(?:\s[^>]*)?>", result, re.I):
        raise ValueError("OUTPUT_REASONING: 结果混入思考标签，请重新生成纯正文")
    if re.match(r"\A(?:以下是(?:修改|改写|润色)后的|修改说明\s*[:：])", result):
        raise ValueError("OUTPUT_PREFACE: 结果不能含修改说明或交付前缀")
    return {"result": result}
